// Aggregations OpenSearch : reference directe au noeud HTTP Request
const agg = $node["HTTP Request"].json.aggregations;

const TERMES_SIGNAL = [
  "WebShell","EXPLOIT","COMPROMISED","MALWARE","TROJAN","ATTACK_RESPONSE","CNC",
  "Cobalt Strike","Empire","Remote Command Execution","Suspicious String","sinkhole",
  "Backdoor","Ransomware","Shellcode","Phishing","Exfiltration","Lateral Movement",
  "Mimikatz","PsExec","Reverse Shell"
];
const TERMES_CONTROLE = [
  "ET DROP","ET CINS","Dshield","Spamhaus","Poor Reputation","Block Listed","DROP SYN"
];
const TERMES_BRUIT = [
  "ET INFO","SURICATA STREAM","SURICATA HTTP","SURICATA TCPv4","SURICATA IPv4",
  "NF - Known Scanner","Not Suspicious Traffic","Windows Update","package management","GNU/Linux APT"
];
const SEUIL_RARETE = 2;

function classer(sig) {
  const s = sig.toLowerCase();
  for (const t of TERMES_SIGNAL) if (s.includes(t.toLowerCase())) return {classe:"SIGNAL",terme:t};
  for (const t of TERMES_BRUIT) if (s.includes(t.toLowerCase())) return {classe:"BRUIT",terme:t};
  for (const t of TERMES_CONTROLE) if (s.includes(t.toLowerCase())) return {classe:"CONTROLE",terme:t};
  return {classe:"INDETERMINE",terme:null};
}

function topIps(map, n) {
  return [...map.entries()].sort((a,b) => b[1]-a[1]).slice(0,n)
    .map(([ip,c]) => `${ip} (${c})`).join(", ") || "non renseignées";
}

function isPrivate(ip) {
  return ip.startsWith("10.") || ip.startsWith("192.168.") ||
         ip.startsWith("172.") || ip === "" || ip === "non renseignées";
}

// Descriptions des regles PostgreSQL
const reglesRows = $input.all().map(i => i.json);
const descMap = new Map();
for (const r of reglesRows) {
  if (r.rule_name && r.rule_description)
    descMap.set(r.rule_name, r.rule_description.substring(0, 250));
}

// Collecte avec deduplication
const signatureMap = new Map();
for (const r of (agg.par_regle?.buckets || [])) {
  const sev = r.severite?.buckets?.[0]?.key || "?";
  const cat = r.categorie?.buckets?.[0]?.key || "?";
  const tech = r.technique?.buckets?.[0]?.key || "non spécifiée";
  for (const s of (r.signatures_suricata?.buckets || [])) {
    const c = classer(s.key);
    if (!signatureMap.has(s.key)) {
      signatureMap.set(s.key, {
        signature: s.key, count: 0,
        regles: new Set(), severites: new Set(),
        categories: new Set(), techniques: new Set(),
        ipsSource: new Map(), ipsCible: new Map(),
        classe: c.classe, motif: c.terme
      });
    }
    const entry = signatureMap.get(s.key);
    entry.count += s.doc_count;
    entry.regles.add(r.key);
    entry.severites.add(sev);
    entry.categories.add(cat);
    entry.techniques.add(tech);
    for (const ip of (s.ips_source?.buckets || [])) {
      const pays = ip.pays?.buckets?.[0]?.key || "?";
      const cle = `${ip.key} [${pays}]`;
      entry.ipsSource.set(cle, (entry.ipsSource.get(cle) || 0) + ip.doc_count);
    }
    for (const ip of (s.ips_cible?.buckets || [])) {
      entry.ipsCible.set(ip.key, (entry.ipsCible.get(ip.key) || 0) + ip.doc_count);
    }
  }
}

const signaux = [], controle = [], bruit = [], indetermine = [];
const ipsALookup = new Set();

for (const entry of signatureMap.values()) {
  const e = {
    signature: entry.signature, count: entry.count,
    regle: [...entry.regles].join(" / "),
    reglesArr: [...entry.regles],
    severite: [...entry.severites].join("/"),
    technique: [...entry.techniques].join("/"),
    srcIps: topIps(entry.ipsSource, 3),
    dstIps: topIps(entry.ipsCible, 3),
    rawSrcIps: [...entry.ipsSource.keys()].slice(0, 3),
    motif: entry.motif
  };
  if (entry.classe === "SIGNAL") {
    signaux.push(e);
    for (const ipL of e.rawSrcIps) {
      const ipOnly = ipL.split(" [")[0].trim();
      if (!isPrivate(ipOnly)) ipsALookup.add(ipOnly);
    }
  }
  else if (entry.classe === "CONTROLE") controle.push(e);
  else if (entry.classe === "BRUIT") bruit.push(e);
  else {
    indetermine.push(e);
    // FIX v12.1 : lookup TI aussi sur les IPs des non-classees
    for (const ipL of e.rawSrcIps) {
      const ipOnly = ipL.split(" [")[0].trim();
      if (!isPrivate(ipOnly)) ipsALookup.add(ipOnly);
    }
  }
}
[signaux, controle, bruit, indetermine].forEach(a => a.sort((x,y) => y.count-x.count));

// Squelette
let compteur = 0;
let sq = "# Synthèse SOC UTMStack — dernières 24h\n\n";
sq += `**Volumes** — Sévérité : ${(agg.par_severite?.buckets||[]).map(b=>`${b.key}: ${b.doc_count}`).join(", ")}. `;
sq += `Statut : ${(agg.par_statut?.buckets||[]).map(b=>`${b.key}: ${b.doc_count}`).join(", ")}.\n\n`;

sq += "## SECTION 1 — SIGNAUX À INVESTIGUER EN PRIORITÉ\n\n";
if (signaux.length === 0) {
  sq += "Aucune signature de menace confirmée sur cette période.\n\n";
} else {
  for (const e of signaux) {
    compteur++;
    sq += `**${e.signature}** — ${e.count} occurrence(s)\n`;
    sq += `- Règle(s) : ${e.regle} | sévérité ${e.severite} | ${e.technique}\n`;
    sq += `- IP sources principales : ${e.srcIps}\n`;
    sq += `- Cibles internes : ${e.dstIps}\n`;
    let desc = null;
    for (const rn of e.reglesArr) if (descMap.has(rn)) { desc = descMap.get(rn); break; }
    if (desc) sq += `- Procédure officielle (extrait) : ${desc}\n`;
    sq += `[COMMENTAIRE_${compteur}]\n\n`;
  }
}

sq += "## SECTION 2 — SOUS CONTRÔLE\n\n";
if (controle.length === 0) {
  sq += "Aucun.\n\n";
} else {
  sq += `${controle.length} signature(s), ${controle.reduce((a,b)=>a+b.count,0)} occurrence(s) :\n`;
  for (const e of controle) sq += `- ${e.signature} : ${e.count}\n`;
  compteur++;
  sq += `\n[COMMENTAIRE_${compteur}]\n\n`;
}

sq += "## SECTION 3 — BRUIT DE FOND\n\n";
if (bruit.length === 0) {
  sq += "Aucun.\n\n";
} else {
  sq += `${bruit.length} signature(s), ${bruit.reduce((a,b)=>a+b.count,0)} occurrence(s) :\n`;
  for (const e of bruit) sq += `- ${e.signature} : ${e.count} (${e.regle})\n`;
  compteur++;
  sq += `\n[COMMENTAIRE_${compteur}]\n\n`;
}

sq += "## SIGNATURES NON CLASSÉES\n\n";
if (indetermine.length === 0) {
  sq += "Aucune.\n\n";
} else {
  for (const e of indetermine) {
    const flag = e.count <= SEUIL_RARETE ? " — **RARETÉ SUSPECTE**" : "";
    compteur++;
    sq += `**${e.signature}** — ${e.count}${flag}\n`;
    sq += `- IP sources : ${e.srcIps} | Cibles : ${e.dstIps}\n`;
    sq += `[COMMENTAIRE_${compteur}]\n\n`;
  }
}

const nbRaretes = indetermine.filter(e => e.count <= SEUIL_RARETE).length;
sq += "## CONCLUSION\n\n";
if (signaux.length > 0) {
  sq += `**${signaux.length} signal(aux) à investiguer** : ${signaux.map(e=>e.signature).join(" ; ")}.\n`;
} else {
  sq += "Aucun signal prioritaire sur cette période.\n";
}
if (nbRaretes > 0) sq += `**${nbRaretes} rareté(s) suspecte(s)** à surveiller.\n`;
sq += "[CONCLUSION]\n";

return [{ json: {
  resume_donnees: sq,
  ips_a_lookup: [...ipsALookup],
  nb_signaux: signaux.length,
  nb_raretes: nbRaretes,
  nb_commentaires: compteur
} }];

const choix = $json.choices?.[0];
const reponse = choix?.message?.content || "";

if (!reponse || reponse.trim() === "") {
  return [{ json: {
    synthese: "⚠️ GÉNÉRATION ÉCHOUÉE — réponse vide ou format API inattendu.",
    generation_complete: false,
    balises_restantes: -1,
    genere_le: new Date().toISOString()
  } }];
}

const balisesRestantes = (reponse.match(/\[COMMENTAIRE_\d+\]|\[CONCLUSION\]/g) || []).length;
let synthese = reponse;
if (balisesRestantes > 0) {
  synthese = "⚠️ GÉNÉRATION INCOMPLÈTE — " + balisesRestantes + " emplacement(s) non rempli(s).\n\n" + reponse;
}
return [{ json: {
  synthese,
  generation_complete: balisesRestantes === 0,
  balises_restantes: balisesRestantes,
  genere_le: new Date().toISOString()
} }];

const synthese = $input.first().json.synthese;
const date = new Date().toISOString().split('T')[0];

return [{ json: { 
  synthese: synthese,
  date: date
} }];

// Transforme la liste d'IPs en items individuels pour les lookups paralleles
const ips = $input.first().json.ips_a_lookup || [];
if (ips.length === 0) {
  return [{ json: { ip: null, aucune_ip: true } }];
}
return ips.map(ip => ({ json: { ip } }));

// Agregation resiliente des 4 feeds TI + historique pour une IP
const ip = $('IPs Signaux').first().json.ip;
if (!ip) return [{ json: { ti_enrichissements: {} } }];

const tiParts = [];

// AbuseIPDB
try {
  const abuse = $('AbuseIPDB Check').first().json;
  if (abuse && abuse.data) {
    const score = abuse.data.abuseConfidenceScore || 0;
    const nbReports = abuse.data.totalReports || 0;
    if (score > 0 || nbReports > 0) {
      tiParts.push(`  * AbuseIPDB : score ${score}/100, ${nbReports} signalement(s)`);
    }
  }
} catch(e) {}

// GreyNoise
try {
  const gn = $('GreyNoise Check').first().json;
  if (gn && (gn.classification || gn.noise !== undefined || gn.riot !== undefined)) {
    const classification = gn.classification || (gn.riot ? "trusted" : "unknown");
    const name = gn.name || "";
    tiParts.push(`  * GreyNoise : ${classification}${name ? " — " + name : ""}`);
  }
} catch(e) {}

// OTX
try {
  const otx = $('OTX Check').first().json;
  if (otx && otx.pulse_info && otx.pulse_info.count > 0) {
    const pulses = otx.pulse_info.pulses.slice(0,3).map(p => p.name).join(", ");
    tiParts.push(`  * OTX : ${otx.pulse_info.count} pulse(s) — ${pulses}`);
  }
} catch(e) {}

// ThreatFox
try {
  const tf = $('ThreatFox Check').first().json;
  if (tf && tf.query_status === "ok" && tf.data && tf.data.length > 0) {
    const malware = tf.data[0].malware_printable || tf.data[0].malware || "inconnu";
    const confidence = tf.data[0].confidence_level || "?";
    tiParts.push(`  * ThreatFox : ${malware}, confiance ${confidence}%`);
  }
} catch(e) {}

// Correlation historique (30 jours)
try {
  const hist = $('Correlation Historique').first().json;
  if (hist && hist.historique_enrichissements && hist.historique_enrichissements[ip]) {
    tiParts.push(hist.historique_enrichissements[ip]);
  }
} catch(e) {}

const tiMap = {};
if (tiParts.length > 0) {
  tiMap[ip] = tiParts.join("\n");
}

return [{ json: { ti_enrichissements: tiMap } }];

const squelette = $node["Code in JavaScript"].json.resume_donnees;
const nbSignaux = $node["Code in JavaScript"].json.nb_signaux;
const nbRaretes = $node["Code in JavaScript"].json.nb_raretes;

// Fusionner tous les enrichissements TI recus
const tiMap = {};
for (const item of $input.all()) {
  if (item.json && item.json.ti_enrichissements) {
    Object.assign(tiMap, item.json.ti_enrichissements);
  }
}

// Injection APRES la ligne "- IP sources principales : ..."
// Format : nouvelle ligne indentee avec les donnees TI
let squeletteTI = squelette;
for (const [ip, ti] of Object.entries(tiMap)) {
  if (!ti || ti.trim() === "") continue;
  // Cherche la ligne contenant cette IP exacte et ajoute le bloc TI dessous
  const ipEscape = ip.replace(/\./g, '\\.').replace(/\[/g, '\\[').replace(/\]/g, '\\]');
  // Match la ligne "- IP sources principales : ... X.X.X.X ..."
  // ou "- IP sources : ... X.X.X.X ..."
  const regex = new RegExp(`(- IP (?:sources principales|sources) : [^\\n]*${ipEscape}[^\\n]*)\\n`, 'g');
  squeletteTI = squeletteTI.replace(regex, `$1\n${ti}\n`);
}

return [{ json: { prompt_enrichi: squeletteTI, nb_signaux: nbSignaux, nb_raretes: nbRaretes } }];

// Corrélation temporelle : cette IP est-elle apparue dans des rapports precedents (30j) ?
const ips = $('IPs Signaux').all().map(i => i.json.ip).filter(Boolean);
const rapports = $input.all().map(i => i.json).filter(r => r.contenu);

function joursDepuis(dateStr) {
  const d = new Date(dateStr);
  const now = new Date();
  return Math.floor((now - d) / (1000 * 60 * 60 * 24));
}

const correlations = {};
for (const ip of ips) {
  const occurrences = rapports.filter(r => r.contenu && r.contenu.includes(ip));
  if (occurrences.length === 0) continue;
  const jours = occurrences.map(r => joursDepuis(r.date_generation)).filter(j => j >= 1); // exclure le jour meme
  if (jours.length === 0) continue;
  const texte = `  * Historique : apparue dans ${jours.length} rapport(s) précédent(s) sur 30 jours (il y a ${jours.slice(0,5).join(", ")} jour(s)) — pattern potentiellement récurrent à surveiller.`;
  correlations[ip] = texte;
}

return [{ json: { historique_enrichissements: correlations } }];
